package bowling

import "errors"

var (
	errNegativeRoll    = errors.New("negative roll is invalid")
	errTooManyPins     = errors.New("pin count exceeds pins on the lane")
	errGameAlreadyOver = errors.New("cannot roll after game is over")
	errGameIncomplete  = errors.New("score cannot be taken until the end of the game")
)

// Game tracks the state of a bowling game as rolls are applied.
type Game struct {
	rolls           []int
	frame           int // 0-9; 10 means the game is over
	rollInFrame     int // 0, 1, or 2 (index of the next roll within the frame)
	pinsRemaining   int // pins still standing in the current lane
	firstRollStrike bool // frame 9 only: whether the first roll was a strike
}

func NewGame() *Game {
	return &Game{
		frame:         0,
		rollInFrame:   0,
		pinsRemaining: 10,
	}
}

func (g *Game) gameOver() bool {
	return g.frame >= 10
}

func (g *Game) advanceFrame() {
	g.frame++
	g.rollInFrame = 0
	g.pinsRemaining = 10
	g.firstRollStrike = false
}

// Roll records a single ball throw, knocking down `pins` pins.
// It returns an error if the roll is invalid or the game is already over.
func (g *Game) Roll(pins int) error {
	if g.gameOver() {
		return errGameAlreadyOver
	}
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 || pins > g.pinsRemaining {
		return errTooManyPins
	}

	g.rolls = append(g.rolls, pins)
	g.pinsRemaining -= pins
	g.rollInFrame++

	if g.frame < 9 {
		// Frames 0-8 end after a strike or two rolls.
		if g.pinsRemaining == 0 || g.rollInFrame == 2 {
			g.advanceFrame()
		}
	} else {
		// Frame 9 (the 10th frame) awards bonus rolls after a strike or spare.
		switch g.rollInFrame {
		case 1:
			if pins == 10 {
				// Strike: two bonus rolls follow.
				g.firstRollStrike = true
				g.pinsRemaining = 10
			}
			// Otherwise one bonus roll follows; pinsRemaining is already correct.
		case 2:
			if g.pinsRemaining == 0 {
				// Cleared (spare, or strike followed by a strike): one bonus roll.
				g.pinsRemaining = 10
			} else if !g.firstRollStrike {
				// Open frame: the game is over.
				g.advanceFrame()
			}
			// If the first roll was a strike, one more bonus roll follows and
			// pinsRemaining is already correct.
		case 3:
			g.advanceFrame()
		}
	}
	return nil
}

// Score returns the total score for a completed game, or an error if the game
// is not yet finished.
func (g *Game) Score() (int, error) {
	if !g.gameOver() {
		return 0, errGameIncomplete
	}
	return g.computeScore(), nil
}

func (g *Game) computeScore() int {
	rolls := g.rolls
	score := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case rolls[i] == 10:
			// Strike: 10 plus the next two rolls.
			score += 10 + rolls[i+1] + rolls[i+2]
			i++
		case rolls[i]+rolls[i+1] == 10:
			// Spare: 10 plus the next roll.
			score += 10 + rolls[i+2]
			i += 2
		default:
			// Open frame: just the two rolls.
			score += rolls[i] + rolls[i+1]
			i += 2
		}
	}
	return score
}

